type ScheduledItem={id:string;scheduled_for:number;status:string;title:string;platform:string;account_name:string}
function LiveCalendar(){
  const client=useQueryClient(),[selected,setSelected]=useState(''),[when,setWhen]=useState(''),[month,setMonth]=useState(()=>{const now=new Date();return new Date(now.getFullYear(),now.getMonth(),1)}),[message,setMessage]=useState('')
  const items=useQuery({queryKey:['schedule'],queryFn:()=>invoke('schedule:list',{}) as Promise<ScheduledItem[]>}),content=useQuery({queryKey:['content-studio'],queryFn:()=>invoke('content:listStudio',{}) as Promise<StudioItem[]>}),approved=content.data?.filter(i=>i.status==='approved')??[]
  const schedule=async()=>{try{await invoke('schedule:create',{contentItemId:selected,scheduledFor:new Date(when).getTime()});setSelected('');setWhen('');setMessage('Added to the calendar. Publishing still requires your action.');await Promise.all([client.invalidateQueries({queryKey:['schedule']}),client.invalidateQueries({queryKey:['content-studio']})])}catch(e){setMessage(e instanceof Error?e.message:'The post could not be scheduled.')}}
  const run=async(id:string)=>{await invoke('publishing:attempt',{scheduledPostId:id});await client.invalidateQueries({queryKey:['schedule']})}
  const first=new Date(month.getFullYear(),month.getMonth(),1),leading=first.getDay(),daysInMonth=new Date(month.getFullYear(),month.getMonth()+1,0).getDate(),cells=Array.from({length:42},(_,index)=>{const day=index-leading+1;return day>0&&day<=daysInMonth?day:null}),byDay=new Map<number,ScheduledItem[]>()
  for(const item of items.data??[]){const date=new Date(item.scheduled_for);if(date.getFullYear()===month.getFullYear()&&date.getMonth()===month.getMonth()){const bucket=byDay.get(date.getDate())??[];bucket.push(item);byDay.set(date.getDate(),bucket)}}
  return <section><div className="page-intro"><div><span className="eyebrow">Supervised delivery</span><h2>Content calendar</h2><p>See the month at a glance, then manage every scheduled platform post below.</p></div><span className="mock-badge">Manual mock publishing</span></div><div className="calendar-workbench"><div className="schedule-panel"><div><span className="eyebrow">Add to calendar</span><h3>Schedule approved content</h3><p>Choose an approved package and the local date and time. Nothing publishes automatically.</p></div><label><span>Approved content</span><select aria-label="Approved content" value={selected} onChange={e=>setSelected(e.target.value)}><option value="">Select a content package</option>{approved.map(i=><option value={i.id} key={i.id}>{i.title}</option>)}</select></label><label><span>Publish date and time</span><input aria-label="Publish date and time" type="datetime-local" value={when} onChange={e=>setWhen(e.target.value)}/></label><button className="primary" disabled={!selected||!when} onClick={schedule}><CalendarDays size={16}/> Add to calendar</button>{message&&<small className="schedule-message" role="status">{message}</small>}</div><div className="month-calendar"><header><div><span className="eyebrow">Monthly plan</span><h3>{month.toLocaleDateString(undefined,{month:'long',year:'numeric'})}</h3></div><div className="month-nav"><button aria-label="Previous month" onClick={()=>setMonth(new Date(month.getFullYear(),month.getMonth()-1,1))}><ChevronLeft size={17}/></button><button onClick={()=>{const now=new Date();setMonth(new Date(now.getFullYear(),now.getMonth(),1))}}>Today</button><button aria-label="Next month" onClick={()=>setMonth(new Date(month.getFullYear(),month.getMonth()+1,1))}><ChevronRight size={17}/></button></div></header><div className="month-weekdays">{['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(day=><span key={day}>{day}</span>)}</div><div className="month-grid">{cells.map((day,index)=><div className={!day?'outside-month':''} key={index}>{day&&<><time>{day}</time>{(byDay.get(day)??[]).slice(0,3).map(item=><span className={`month-post month-post-${item.status}`} title={`${item.title} · ${platformLabels[item.platform]??item.platform}`} key={item.id}>{item.title}<small>{platformLabels[item.platform]??item.platform}</small></span>)}{(byDay.get(day)?.length??0)>3&&<em>+{(byDay.get(day)?.length??0)-3} more</em>}</>}</div>)}</div></div></div><div className="queue-heading"><div><span className="eyebrow">Delivery queue</span><h3>Scheduled platform posts</h3></div><span>{items.data?.length??0} total</span></div><div className="oven-queue">{items.data?.length?items.data.map(item=><article className="oven-ticket" key={item.id}><time>{new Date(item.scheduled_for).toLocaleString()}</time><div><strong>{item.title}</strong><span>{platformLabels[item.platform]??item.platform} · {item.account_name}</span></div><span className={`content-status status-${item.status}`}>{item.status}</span>{item.status!=='published'&&<button className="primary compact" onClick={()=>run(item.id)}>{item.status==='failed'?'Retry mock publish':'Run mock publish'}</button>}</article>):<div className="empty"><h3>Nothing scheduled yet</h3><p>Approve content at the Review Desk, then add it to this calendar.</p></div>}</div></section>}

function Calendar() { const days = Array.from({length: 35},(_,i)=>i-2); return <section><div className="page-intro"><div><span className="eyebrow">Planning view</span><h2>Content calendar</h2><p>Approved content will appear here before it is scheduled.</p></div><span className="mock-badge">Publishing is mocked</span></div><div className="calendar"><div className="calendar-head"><h3>August 2026</h3></div><div className="weekdays">{['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d=><span key={d}>{d}</span>)}</div><div className="calendar-grid">{days.map((day,i)=><div className={day < 1 ? 'outside' : ''} key={i}>{day > 0 ? day : ''}{day === 7 && <span className="calendar-item">Friday feature · Review</span>}{day === 14 && <span className="calendar-item approved">Pepperoni post · Approved</span>}</div>)}</div></div></section> }

